import json
def f(g):
    h,w=len(g),len(g[0])
    cnt={}
    for r in g:
        for x in r: cnt[x]=cnt.get(x,0)+1
    bg=max(cnt,key=lambda v:cnt[v])          # background = most common
    q=deque(); seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True;q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True;q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True;q.append((ni,nj))
    out=[]
    for i in range(h):
        row=[]
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]: row.append(4)      # enclosed background
            elif g[i][j]!=bg: row.append(g[i][j])                 # shape cells kept
            else: row.append(bg)                                   # open background
        out.append(row)
    return out
